C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -NoProfile -Command '& {
$nodes = Invoke-RestMethod -Uri "http://127.0.0.1:3080/v3/projects/CampusNetwork_02/nodes"
foreach ($n in $nodes) {
  $u1 = "http://127.0.0.1:3080/v3/projects/CampusNetwork_02/nodes/$($n.node_id)/command?cmd=display%20current-configuration"
  $u0 = "http://127.0.0.1:3080/v3/projects/CampusNetwork-for-perf/nodes/$($n.node_id)/command?cmd=display%20current-configuration"
  $a = (Invoke-RestMethod -Uri $u1).output
  $b = (Invoke-RestMethod -Uri $u0).output
  if ($a -notlike "Error:*" -and $b -notlike "Error:*") {
    $aa = $a -split "\r?\n" | Where-Object { $_ -notmatch "^!Last configuration" }
    $bb = $b -split "\r?\n" | Where-Object { $_ -notmatch "^!Last configuration" }
    $d = Compare-Object -ReferenceObject $bb -DifferenceObject $aa
    if ($d) {
      Write-Output "===== $($n.name) ====="
      $d | ForEach-Object { Write-Output "$($_.SideIndicator) $($_.InputObject)" }
    }
  }
}
}'

